322	fn draw(
323	    stdout: &mut impl Write,
324	    sessions: &[DisplaySession],
325	    local_sessions: &HashSet<String>,
326	    sel: usize,
327	    w: usize,
328	    h: usize,
329	    flash: Option<&str>,
330	) -> io::Result<()> {
331	    let t = crate::theme::get();
332	    // Reserve the leading cell only if at least one row will use the star.
333	    // Otherwise we'd lose two columns of width for no visible benefit (e.g.
334	    // when not invoked from inside a tracked repo).
335	    let any_local = sessions.iter().any(|s| local_sessions.contains(&s.session_id));
336	
337	    let content_h = h.saturating_sub(1);
338	    let scroll = if sel >= content_h { sel + 1 - content_h } else { 0 };
339	
340	    // Pre-compute column widths
341	    let name_w = sessions.iter().map(|s| s.session_name.trim().chars().count()).max().unwrap_or(0).min(40);
342	    let cwd_w  = sessions.iter().map(|s| short_cwd(&s.cwd).chars().count()).max().unwrap_or(0);
343	    let branch_w = sessions.iter().map(|s| s.branch.chars().count()).max().unwrap_or(0);
344	    let author_w = sessions.iter().map(|s| s.author.chars().count()).max().unwrap_or(0);
345	    let agent_w  = sessions.iter().map(|s| s.agent_name.chars().count()).max().unwrap_or(0);
346	
347	    execute!(stdout, cursor::MoveTo(0, 0))?;
348	
349	    for row in 0..content_h {
350	        execute!(stdout, cursor::MoveTo(0, row as u16))?;
351	        let idx = scroll + row;
352	        if idx >= sessions.len() {
353	            execute!(stdout, terminal::Clear(ClearType::UntilNewLine))?;
354	            continue;
355	        }
356	
357	        let s = &sessions[idx];
358	        let is_sel = idx == sel;
359	
360	        let id_short: String = s.session_id.chars().take(8).collect();
361	        let ts = relative_time(s.updated_at);
362	        let age = (Utc::now() - s.updated_at).num_seconds().max(0);
363	        let dot_col = match age {
364	            a if a < 900   => t.fresh,
365	            a if a < 3_600 => t.moderate,
366	            _              => t.text_dim,
367	        };
368	        let (meta_col, dot_char) = if s.backed_up {
369	            (t.backed_meta, "*")
370	        } else {
371	            (t.unbacked_meta, "·")
372	        };
373	        // Name color is driven by whether the user explicitly named the
374	        // session (`/rename` or custom-title), not by whether it's been
375	        // checkpointed. Explicit names always pop; derived first-prompt
376	        // fallbacks render dim regardless of backed_up.
377	        let name_col = if s.name_is_explicit {
378	            t.backed_name
379	        } else if s.backed_up {
380	            t.text_secondary
381	        } else {
382	            t.unbacked_name
383	        };
384	        let branch_col = if s.backed_up { t.link } else { t.stale };
385	
386	        let clean = session_list::sanitize_one_line(&s.session_name);
387	        let name: String = clean.chars().take(name_w).collect();
388	        let name_padded = format!("{:<name_w$}", name);
389	
390	        let cwd_short = short_cwd(&s.cwd);
391	        let cwd_padded = format!("{:<cwd_w$}", cwd_short);
392	
393	        let star_prefix = if any_local {
394	            if local_sessions.contains(&s.session_id) {
395	                format!("\x1b[{fc}m★\x1b[0m ", fc = t.fresh)
396	            } else {
397	                "  ".to_string()
398	            }
399	        } else {
400	            String::new()
401	        };
402	
403	        let mut line = format!(
404	            "{star_prefix}\x1b[{dot_col}m{dot_char}\x1b[0m \x1b[{name_col}m{name_padded}\x1b[0m  \x1b[{dm}m{cwd_padded}\x1b[0m",
405	            dm = t.text_dim,
406	        );
407	
408	        if branch_w > 0 {
409	            let b: String = s.branch.chars().take(branch_w).collect();
410	            let pad = " ".repeat(branch_w - b.chars().count());
411	            line.push_str(&format!("  \x1b[{branch_col}m{b}{pad}\x1b[0m"));
412	        }
413	
414	        if author_w > 0 {
415	            let a: String = s.author.chars().take(author_w).collect();
416	            let pad = " ".repeat(author_w - a.chars().count());
417	            line.push_str(&format!("  \x1b[{dm}m{a}{pad}\x1b[0m", dm = t.text_dim));
418	        }
419	
420	        if agent_w > 0 {
421	            let a: String = s.agent_name.chars().take(agent_w).collect();
422	            let pad = " ".repeat(agent_w - a.chars().count());
423	            if s.backed_up {
424	                let col = agent_color(&s.agent_name);
425	                line.push_str(&format!("  \x1b[38;5;{col}m{a}{pad}\x1b[0m"));
426	            } else {
427	                line.push_str(&format!("  \x1b[{st}m{a}{pad}\x1b[0m", st = t.stale));
428	            }
429	        }
430	
431	        line.push_str(&format!("  \x1b[{meta_col}m{id_short}  {ts}\x1b[0m"));
432	
433	        if is_sel {
434	            let bg = crate::theme::get().sel_bg;
435	            let colored = super::with_bg(&line, bg);
436	            let vis = super::visible_width(&line);
437	            let pad = w.saturating_sub(vis);
438	            write!(stdout, "\x1b[{bg}m{colored}{}\x1b[0m", " ".repeat(pad))?;
439	        } else {
440	            write!(stdout, "{line}")?;
441	            execute!(stdout, terminal::Clear(ClearType::UntilNewLine))?;
442	        }
443	    }
444	
445	    let base = format!(
446	        "  {} sessions   ↑↓/jk navigate   space: view   r: resume   d: delete   s: new session   n: new worktree   t: tidy   / search   q: quit  ",
447	        sessions.len()
448	    );
449	    let bar = if let Some(msg) = flash {
450	        let skip = msg.chars().count();
451	        let rest: String = base.chars().skip(skip).collect();
452	        format!("{msg}{rest}")
453	    } else { base };
454	    let display: String = bar.chars().take(w).collect();
455	    let padded = format!("{:<width$}", display, width = w);
456	    execute!(stdout, cursor::MoveTo(0, (h - 1) as u16))?;
457	    write!(stdout, "\x1b[7m{padded}\x1b[0m")?;
458	
459	    stdout.flush()
460	}
461	
462	use super::agent_color;
