464	fn relative_time(dt: DateTime<Utc>) -> String {
465	    let secs = (Utc::now() - dt).num_seconds().max(0);
466	    if secs < 604_800 {
467	        match secs {
468	            s if s < 60     => "just now".to_string(),
469	            s if s < 3_600  => format!("{} min{} ago", s/60,     if s/60==1     {""} else {"s"}),
470	            s if s < 86_400 => format!("{} hr{} ago",  s/3_600,  if s/3_600==1  {""} else {"s"}),
471	            s               => format!("{} day{} ago", s/86_400, if s/86_400==1 {""} else {"s"}),
472	        }
473	    } else {
474	        dt.with_timezone(&Local).format("%m/%d/%y").to_string()
475	    }
476	}
477	
478	fn short_cwd(cwd: &str) -> String {
479	    let home = std::env::var("HOME").unwrap_or_default();
480	    let path = if !home.is_empty() && cwd.starts_with(&home) {
481	        format!("~{}", &cwd[home.len()..])
482	    } else {
483	        cwd.to_string()
484	    };
485	    let parts: Vec<&str> = path.trim_end_matches('/').split('/').filter(|s| !s.is_empty()).collect();
486	    match parts.len() {
487	        0 => "/".to_string(),
488	        1 => format!("/{}", parts[0]),
489	        2 => format!("{}/{}", parts[0], parts[1]),
490	        _ => format!("…/{}/{}", parts[parts.len() - 2], parts[parts.len() - 1]),
491	    }
492	}
