91	    if !io::stdout().is_terminal() && cd_file.is_none() {
92	        // Plain list when truly non-interactive (piped, no wrapper)
93	        let cur_idx = find_repo_for_cwd(&repos);
94	        for (i, repo) in repos.iter().enumerate() {
95	            let dot = if cur_idx == Some(i) { "*" } else { " " };
96	            println!("{dot} {}  {}  {}", repo.name, repo.directory, repo.remote);
97	        }
98	        return Ok(false);
99	    }
100	
101	    // Register panic hook to restore terminal
102	    let orig_hook = std::panic::take_hook();
103	    std::panic::set_hook(Box::new(move |info| {
104	        let mut out = io::stdout();
105	        let _ = execute!(out, LeaveAlternateScreen, cursor::Show);
106	        let _ = terminal::disable_raw_mode();
107	        orig_hook(info);
108	    }));
109	
110	    let mut stdout = io::stdout();
111	    terminal::enable_raw_mode()?;
112	    execute!(stdout, EnterAlternateScreen, cursor::Hide)?;
113	
114	    let start_repo = find_repo_for_cwd(&repos);
115	
116	    let outcome = tui_loop(&mut stdout, &mut repos, cd_file.is_some(), start_repo);
117	
118	    execute!(stdout, LeaveAlternateScreen, cursor::Show)?;
119	    terminal::disable_raw_mode()?;
120	
121	    let outcome = outcome?;
122	    let quit_app = matches!(outcome, Some(TuiOutcome::Quit));
123	    match outcome {
124	        Some(TuiOutcome::Quit) => {}
125	        Some(TuiOutcome::CdTo(path)) => {
126	            if let Some(file) = cd_file {
127	                std::fs::write(&file, &path)?;
128	            }
129	        }
130	        Some(TuiOutcome::ResumeSession { id, cwd }) => {
131	            super::show::resume_session(&id, &cwd);
132	        }
133	        Some(TuiOutcome::LaunchNewSession(cfg)) => { launch_new_session(cfg); }
134	        None => {}
135	    }
136	
137	    Ok(quit_app)
138	}
