140	enum TuiOutcome {
141	    /// User pressed q somewhere in the TUI (or a nested viewer). Parent
142	    /// callers should propagate as a full-app exit.
143	    Quit,
144	    CdTo(String),
145	    ResumeSession { id: String, cwd: String },
146	    LaunchNewSession(NewSessionConfig),
147	}
148	
149	enum Screen {
150	    Repos { sel: usize },
151	    Sessions { repo_idx: usize, sel: usize, sessions: Vec<RepoSession>, worktrees: Vec<RepoWorktree> },
152	}
153	
154	fn tui_loop(stdout: &mut impl Write, repos: &mut Vec<Repository>, has_cd: bool, start_repo: Option<usize>) -> Result<Option<TuiOutcome>> {
155	    let current_repo_idx = find_repo_for_cwd(repos);
156	    let current_repo_dir: Option<String> = current_repo_idx
157	        .and_then(|i| repos.get(i))
158	        .map(|r| r.directory.clone());
159	
160	    let start_sel = current_repo_idx.unwrap_or(0);
161	
162	    // Navigation stack — back pops; when empty the TUI exits.
163	    // When starting inside a tracked repo, seed the stack with the repos list
164	    // underneath so pressing Back always returns to it rather than exiting.
165	    let mut stack: Vec<Screen> = if let Some(idx) = start_repo.filter(|&i| i < repos.len()) {
166	        let sessions = session_list::fetch(Scope::Repo(&repos[idx]), true);
167	        let worktrees = fetch_worktrees(&repos[idx].directory);
168	        vec![
169	            Screen::Repos { sel: idx },
170	            Screen::Sessions { repo_idx: idx, sel: 0, sessions, worktrees },
171	        ]
172	    } else {
173	        vec![Screen::Repos { sel: start_sel }]
174	    };
175	
176	    let mut awaiting_delete = false;
177	    let mut flash: Option<&'static str> = None;
178	
179	    // Commands produced inside match arms, executed after the borrow ends.
180	    enum Cmd {
181	        None,
182	        Break,
183	        Back,
184	        PushSessions(usize),
185	        Cd(String),
186	        ShowSession(String),
187	        ResumeSession(String, String), // (session_id, repo_dir)
188	        DeleteSession(String),         // session_id
189	        Discover,
190	        Search(String),
191	        NewWorktree(String), // branch name
192	        NewSession(NewSessionConfig),
193	        Tidy,
194	        Redraw,
195	    }
196	
197	    loop {
198	        let (w, h) = terminal::size().unwrap_or((120, 40));
199	        let w = w as usize;
200	        let h = h as usize;
201	
202	        match stack.last().unwrap() {
203	            Screen::Repos { sel } => draw_repos(stdout, repos, *sel, current_repo_dir.as_deref(), w, h, has_cd)?,
204	            Screen::Sessions { repo_idx, sel, sessions, worktrees } => {
205	                draw_sessions(stdout, repos, *repo_idx, sessions, worktrees, *sel, w, h, flash)?
206	            }
207	        }
208	
209	        let cmd = match event::read()? {
210	            Event::Key(k) => match stack.last_mut().unwrap() {
211	                Screen::Repos { sel } => match k.code {
212	                    KeyCode::Char('q') => Cmd::Break,
213	                    KeyCode::Esc => Cmd::Back,
214	                    KeyCode::Char('c') if k.modifiers.contains(crossterm::event::KeyModifiers::CONTROL) => {
215	                        execute!(stdout, LeaveAlternateScreen, cursor::Show).ok();
216	                        terminal::disable_raw_mode().ok();
217	                        std::process::exit(0);
218	                    }
219	                    KeyCode::Up   | KeyCode::Char('k') => { if *sel > 0 { *sel -= 1; } Cmd::None }
220	                    KeyCode::Down | KeyCode::Char('j') => { if *sel + 1 < repos.len() { *sel += 1; } Cmd::None }
221	                    KeyCode::Char('g') => { *sel = 0; Cmd::None }
222	                    KeyCode::Char('G') => { *sel = repos.len().saturating_sub(1); Cmd::None }
223	                    KeyCode::Char(' ') | KeyCode::Right => Cmd::PushSessions(*sel),
224	                    KeyCode::Char('c') if has_cd => Cmd::Cd(repos[*sel].directory.clone()),
225	                    KeyCode::Char('s') => {
226	                        let repo_dir = repos[*sel].directory.clone();
227	                        match new_session_wizard(stdout, &repo_dir, w, h) {
228	                            Some(cfg) => Cmd::NewSession(cfg),
229	                            None => Cmd::Redraw,
230	                        }
231	                    }
232	                    KeyCode::Char('/') => match super::collect_search_query(stdout, w, h) {
233	                        Some(q) if !q.trim().is_empty() => Cmd::Search(q),
234	                        _ => Cmd::Redraw,
235	                    },
236	                    KeyCode::Char('d') => Cmd::Discover,
237	                    _ => Cmd::None,
238	                },
239	                Screen::Sessions { sel, sessions, repo_idx, .. } => match k.code {
240	                    KeyCode::Char('q') => Cmd::Break,
241	                    KeyCode::Char('c') if k.modifiers.contains(crossterm::event::KeyModifiers::CONTROL) => {
242	                        execute!(stdout, LeaveAlternateScreen, cursor::Show).ok();
243	                        terminal::disable_raw_mode().ok();
244	                        std::process::exit(0);
245	                    }
246	                    KeyCode::Esc | KeyCode::Char('h') | KeyCode::Left => Cmd::Back,
247	                    KeyCode::Up   | KeyCode::Char('k') => { if *sel > 0 { *sel -= 1; } Cmd::None }
248	                    KeyCode::Down | KeyCode::Char('j') => { if *sel + 1 < sessions.len() { *sel += 1; } Cmd::None }
249	                    KeyCode::Char('g') => { *sel = 0; Cmd::None }
250	                    KeyCode::Char('G') => { *sel = sessions.len().saturating_sub(1); Cmd::None }
251	                    KeyCode::Char(' ') | KeyCode::Right => {
252	                        if sessions.is_empty() { Cmd::None }
253	                        else { Cmd::ShowSession(sessions[*sel].session_id.clone()) }
254	                    }
255	                    KeyCode::Char('r') => {
256	                        if sessions.is_empty() { Cmd::None }
257	                        else { Cmd::ResumeSession(sessions[*sel].session_id.clone(), repos[*repo_idx].directory.clone()) }
258	                    }
259	                    KeyCode::Char('d') if !sessions.is_empty() => {
260	                        awaiting_delete = true;
261	                        flash = Some("  Delete session? Press y to confirm, any other key to cancel  ");
262	                        Cmd::None
263	                    }
264	                    KeyCode::Char('y') if awaiting_delete => {
265	                        awaiting_delete = false;
266	                        flash = None;
267	                        Cmd::DeleteSession(sessions[*sel].session_id.clone())
268	                    }
269	                    KeyCode::Char('/') => match super::collect_search_query(stdout, w, h) {
270	                        Some(q) if !q.trim().is_empty() => Cmd::Search(q),
271	                        _ => Cmd::Redraw,
272	                    },
273	                    KeyCode::Char('n') => match super::collect_text_input(stdout, "  new worktree branch: ", w, h) {
274	                        Some(b) if !b.trim().is_empty() => Cmd::NewWorktree(b.trim().to_string()),
275	                        _ => Cmd::Redraw,
276	                    },
277	                    KeyCode::Char('s') => {
278	                        let repo_dir = repos[*repo_idx].directory.clone();
279	                        match new_session_wizard(stdout, &repo_dir, w, h) {
280	                            Some(cfg) => Cmd::NewSession(cfg),
281	                            None => Cmd::Redraw,
282	                        }
283	                    }
284	                    KeyCode::Char('t') => Cmd::Tidy,
285	                    _ => { awaiting_delete = false; flash = None; Cmd::None }
286	                },
287	            },
288	            Event::Resize(_, _) => Cmd::Redraw,
289	            _ => Cmd::None,
290	        };
291	
292	        match cmd {
293	            Cmd::None => {}
294	            Cmd::Break => return Ok(Some(TuiOutcome::Quit)),
295	            Cmd::Back => {
296	                stack.pop();
297	                if stack.is_empty() { break; }
298	            }
299	            Cmd::PushSessions(idx) => {
300	                let sessions = session_list::fetch(Scope::Repo(&repos[idx]), true);
301	                let worktrees = fetch_worktrees(&repos[idx].directory);
302	                stack.push(Screen::Sessions { repo_idx: idx, sel: 0, sessions, worktrees });
303	            }
304	            Cmd::Cd(path) => return Ok(Some(TuiOutcome::CdTo(path))),
305	            Cmd::ResumeSession(id, cwd) => return Ok(Some(TuiOutcome::ResumeSession { id, cwd })),
306	            Cmd::DeleteSession(id) => {
307	                super::clean::remove_session(&id).ok();
308	                if let Some(Screen::Sessions { sel, sessions, .. }) = stack.last_mut() {
309	                    sessions.retain(|s| s.session_id != id);
310	                    if *sel >= sessions.len() && !sessions.is_empty() { *sel = sessions.len() - 1; }
311	                }
312	                execute!(stdout, terminal::Clear(ClearType::All)).ok();
313	            }
314	            Cmd::ShowSession(id) => {
315	                execute!(stdout, LeaveAlternateScreen, cursor::Show).ok();
316	                terminal::disable_raw_mode().ok();
317	                let quit_app = super::show::run(&id).unwrap_or(false);
318	                terminal::enable_raw_mode().ok();
319	                if quit_app { return Ok(Some(TuiOutcome::Quit)); }
320	                execute!(stdout, EnterAlternateScreen, cursor::Hide).ok();
321	                execute!(stdout, terminal::Clear(ClearType::All)).ok();
322	            }
323	            Cmd::Search(query) => {
324	                execute!(stdout, LeaveAlternateScreen, cursor::Show).ok();
325	                terminal::disable_raw_mode().ok();
326	                let quit_app = super::search::run(&query, 10, false).unwrap_or(false);
327	                terminal::enable_raw_mode().ok();
328	                if quit_app { return Ok(Some(TuiOutcome::Quit)); }
329	                execute!(stdout, EnterAlternateScreen, cursor::Hide).ok();
330	                execute!(stdout, terminal::Clear(ClearType::All)).ok();
331	            }
332	            Cmd::NewWorktree(branch) => {
333	                if let Some(Screen::Sessions { repo_idx, worktrees, .. }) = stack.last_mut() {
334	                    let repo_dir = &repos[*repo_idx].directory;
335	                    let notification = create_worktree(repo_dir, &branch);
336	                    // Refresh the worktree list whether or not it succeeded.
337	                    *worktrees = fetch_worktrees(repo_dir);
338	                    // Show the result in the status bar until the next keypress.
339	                    let (tw, th) = terminal::size().unwrap_or((120, 40));
340	                    let msg: String = notification.chars().take(tw as usize).collect();
341	                    let padded = format!("{:<width$}", msg, width = tw as usize);
342	                    execute!(stdout, cursor::MoveTo(0, th - 1)).ok();
343	                    write!(stdout, "\x1b[7m{padded}\x1b[0m").ok();
344	                    stdout.flush().ok();
345	                }
346	            }
347	            Cmd::NewSession(cfg) => {
348	                return Ok(Some(TuiOutcome::LaunchNewSession(cfg)));
349	            }
350	            Cmd::Tidy => {
351	                let repo_idx_opt = if let Some(Screen::Sessions { repo_idx, .. }) = stack.last() {
352	                    Some(*repo_idx)
353	                } else {
354	                    None
355	                };
356	                if let Some(repo_idx) = repo_idx_opt {
357	                    let repo = &repos[repo_idx];
358	                    let (tw, th) = terminal::size().unwrap_or((120, 40));
359	                    let changed = super::tidy::tui_tidy(
360	                        stdout,
361	                        std::slice::from_ref(repo),
362	                        7,
363	                        false,
364	                        tw as usize,
365	                        th as usize,
366	                    );
367	                    if changed {
368	                        if let Some(Screen::Sessions { worktrees, .. }) = stack.last_mut() {
369	                            *worktrees = fetch_worktrees(&repos[repo_idx].directory);
370	                        }
371	                    }
372	                    execute!(stdout, terminal::Clear(ClearType::All)).ok();
373	                }
374	            }
375	            Cmd::Redraw => { execute!(stdout, terminal::Clear(ClearType::All)).ok(); }
376	            Cmd::Discover => {
377	                let (tw, th) = terminal::size().unwrap_or((120, 40));
378	                let scanning = format!("{:<width$}", "  Scanning for new repos…", width = tw as usize);
379	                execute!(stdout, cursor::MoveTo(0, th - 1)).ok();
380	                write!(stdout, "\x1b[7m{scanning}\x1b[0m").ok();
381	                stdout.flush().ok();
382	
383	                let known: std::collections::HashSet<String> = repos.iter().map(|r| r.directory.clone()).collect();
384	                let candidates = super::discover::scan_candidates(&known);
385	
386	                if candidates.is_empty() {
387	                    let msg = format!("{:<width$}", "  No new GitHub repos found in Claude session history — press any key  ", width = tw as usize);
388	                    execute!(stdout, cursor::MoveTo(0, th - 1)).ok();
389	                    write!(stdout, "\x1b[7m{msg}\x1b[0m").ok();
390	                    stdout.flush().ok();
391	                    event::read().ok();
392	                } else if let Some(selected) = super::discover::tui_discover(stdout, candidates, tw as usize, th as usize) {
393	                    if !selected.is_empty() {
394	                        if let Ok(conn) = crate::db::connect() {
395	                            super::discover::register_and_backfill(&conn, &selected).ok();
396	                            if let Ok(new_repos) = fetch_repos(&conn) {
397	                                *repos = new_repos;
398	                            }
399	                        }
400	                    }
401	                }
402	                execute!(stdout, terminal::Clear(ClearType::All)).ok();
403	            }
404	        }
405	    }
406	
407	    Ok(None)
408	}
