410	// ── Renderers ─────────────────────────────────────────────────────────────────
411	
412	fn draw_repos(
413	    stdout: &mut impl Write,
414	    repos: &[Repository],
415	    sel: usize,
416	    current_repo_dir: Option<&str>,
417	    w: usize,
418	    h: usize,
419	    has_cd: bool,
420	) -> io::Result<()> {
421	    use crossterm::queue;
422	    let t = crate::theme::get();
423	    let content_h = h.saturating_sub(1);
424	    let mut buf: Vec<u8> = Vec::with_capacity((w + 40) * (h + 2));
425	    let mut row = 0usize;
426	
427	    let name_w = repos.iter().map(|r| r.name.chars().count()).max().unwrap_or(0);
428	    let dir_w  = repos.iter().map(|r| r.directory.chars().count()).max().unwrap_or(0);
429	
430	    for (i, repo) in repos.iter().enumerate() {
431	        if row >= content_h { break }
432	
433	        let is_sel = i == sel;
434	        let is_cur = current_repo_dir == Some(repo.directory.as_str());
435	        let dot_col = if is_cur { t.fresh } else { t.text_dim };
436	
437	        let name_padded = format!("{:<name_w$}", repo.name);
438	        let dir_padded  = format!("{:<dir_w$}",  repo.directory);
439	        let line = format!(
440	            "\x1b[{dot_col}m*\x1b[0m \x1b[{pm}m{name_padded}\x1b[0m  \x1b[{dm}m{dir_padded}  {}\x1b[0m",
441	            repo.remote, pm = t.text_primary, dm = t.text_dim,
442	        );
443	
444	        super::render_row(&mut buf, &line, is_sel, row, w)?;
445	        row += 1;
446	    }
447	
448	    while row < content_h {
449	        queue!(buf, cursor::MoveTo(0, row as u16), terminal::Clear(ClearType::UntilNewLine))?;
450	        row += 1;
451	    }
452	
453	    let cd_hint = if has_cd { "   c: cd" } else { "" };
454	    let bar = format!(
455	        "  {} repos   ↑↓/jk navigate   space: sessions   s: new session   d: discover   / search{}   q: quit  ",
456	        repos.len(), cd_hint
457	    );
458	    super::draw_statusbar(&mut buf, &bar, w, h)?;
459	
460	    stdout.write_all(&buf)?;
461	    stdout.flush()
462	}
463	
464	fn draw_sessions(
465	    stdout: &mut impl Write,
466	    repos: &[Repository],
467	    repo_idx: usize,
468	    sessions: &[RepoSession],
469	    worktrees: &[RepoWorktree],
470	    sel: usize,
471	    w: usize,
472	    h: usize,
473	    flash: Option<&str>,
474	) -> io::Result<()> {
475	    use crossterm::queue;
476	    let t = crate::theme::get();
477	    let content_h = h.saturating_sub(2); // header + status bar
478	    let mut buf: Vec<u8> = Vec::with_capacity((w + 40) * (h + 2));
479	
480	    // Header row
481	    queue!(buf, cursor::MoveTo(0, 0), terminal::Clear(ClearType::UntilNewLine))?;
482	    write!(buf, "\x1b[{hd}m{}\x1b[0m", repos[repo_idx].name, hd = t.header)?;
483	    let mut row = 1usize;
484	
485	    // ── Worktrees ────────────────────────────────────────────────────────────
486	    if !worktrees.is_empty() {
487	        for wt in worktrees.iter().take(content_h.saturating_sub(row + 1)) {
488	            if row >= content_h { break; }
489	
490	            let (branch_col, branch_label) = if wt.branch == "(detached)" {
491	                (t.error, format!("detached:{}", &wt.head))
492	            } else if wt.is_main {
493	                (t.accent, wt.branch.clone())
494	            } else {
495	                (t.link, wt.branch.clone())
496	            };
497	
498	            let path_short = super::short_path(&wt.path);
499	            let line = format!(
500	                "\x1b[{dm}m  @ \x1b[{branch_col}m{branch_label}\x1b[0m  \x1b[{dm}m{path_short}\x1b[0m",
501	                dm = t.text_dim,
502	            );
503	            queue!(buf, cursor::MoveTo(0, row as u16), terminal::Clear(ClearType::UntilNewLine))?;
504	            write!(buf, "{line}")?;
505	            row += 1;
506	        }
507	
508	        if row < content_h {
509	            queue!(buf, cursor::MoveTo(0, row as u16), terminal::Clear(ClearType::UntilNewLine))?;
510	            row += 1;
511	        }
512	    }
513	
514	    // ── Sessions ─────────────────────────────────────────────────────────────
515	    let sessions_start = row;
516	    let sessions_h = content_h.saturating_sub(sessions_start);
517	    let scroll = if sel >= sessions_h { sel + 1 - sessions_h } else { 0 };
518	
519	    if sessions.is_empty() {
520	        if row < content_h {
521	            queue!(buf, cursor::MoveTo(0, row as u16), terminal::Clear(ClearType::UntilNewLine))?;
522	            write!(buf, "\x1b[{dm}m  no sessions found\x1b[0m", dm = t.text_dim)?;
523	            row += 1;
524	        }
525	    } else {
526	        let name_w   = sessions.iter().map(|s| s.session_name.trim().chars().count()).max().unwrap_or(0).min(40);
527	        let branch_w = sessions.iter().map(|s| s.branch.chars().count()).max().unwrap_or(0);
528	        let author_w = sessions.iter().map(|s| s.author.chars().count()).max().unwrap_or(0);
529	        let agent_w  = sessions.iter().map(|s| s.agent_name.chars().count()).max().unwrap_or(0);
530	
531	        for (i, s) in sessions.iter().enumerate().skip(scroll) {
532	            if row >= content_h { break; }
533	
534	            let id_short: String = s.session_id.chars().take(8).collect();
535	            let ts = relative_time(s.updated_at);
536	            let clean = session_list::sanitize_one_line(&s.session_name);
537	            let name: String = clean.chars().take(name_w).collect();
538	            let age = (Utc::now() - s.updated_at).num_seconds().max(0);
539	            let dot_col = match age {
540	                a if a < 900   => t.fresh,
541	                a if a < 3_600 => t.moderate,
542	                _              => t.text_dim,
543	            };
544	
545	            let (meta_col, dot_char) = if s.backed_up {
546	                (t.backed_meta, "*")
547	            } else {
548	                (t.unbacked_meta, "·")
549	            };
550	            let name_col = if s.name_is_explicit {
551	                t.backed_name
552	            } else if s.backed_up {
553	                t.text_secondary
554	            } else {
555	                t.unbacked_name
556	            };
557	            let branch_col = if s.backed_up { t.link } else { t.stale };
558	
559	            let name_padded = format!("{:<name_w$}", name);
560	            let mut line = format!("\x1b[{dot_col}m{dot_char}\x1b[0m \x1b[{name_col}m{name_padded}\x1b[0m");
561	
562	            if branch_w > 0 {
563	                let b: String = s.branch.chars().take(branch_w).collect();
564	                let pad = " ".repeat(branch_w - b.chars().count());
565	                line.push_str(&format!("  \x1b[{branch_col}m{b}{pad}\x1b[0m"));
566	            }
567	
568	            if author_w > 0 {
569	                let a: String = s.author.chars().take(author_w).collect();
570	                let pad = " ".repeat(author_w - a.chars().count());
571	                line.push_str(&format!("  \x1b[{dm}m{a}{pad}\x1b[0m", dm = t.text_dim));
572	            }
573	
574	            if agent_w > 0 {
575	                let a: String = s.agent_name.chars().take(agent_w).collect();
576	                let pad = " ".repeat(agent_w - a.chars().count());
577	                if s.backed_up {
578	                    let col = agent_color(&s.agent_name);
579	                    line.push_str(&format!("  \x1b[38;5;{col}m{a}{pad}\x1b[0m"));
580	                } else {
581	                    line.push_str(&format!("  \x1b[{st}m{a}{pad}\x1b[0m", st = t.stale));
582	                }
583	            }
584	
585	            line.push_str(&format!("  \x1b[{meta_col}m{id_short}  {ts}\x1b[0m"));
586	
587	            super::render_row(&mut buf, &line, i == sel, row, w)?;
588	            row += 1;
589	        }
590	    }
591	
592	    while row < content_h {
593	        queue!(buf, cursor::MoveTo(0, row as u16), terminal::Clear(ClearType::UntilNewLine))?;
594	        row += 1;
595	    }
596	
597	    let base = format!(
598	        "  {} sessions   ↑↓/jk navigate   space: view   r: resume   d: delete   s: new session   n: new worktree   t: tidy   / search   ←/h: back   q: quit  ",
599	        sessions.len()
600	    );
601	    let bar = if let Some(msg) = flash {
602	        let skip = msg.chars().count();
603	        let rest: String = base.chars().skip(skip).collect();
604	        format!("{msg}{rest}")
605	    } else { base };
606	    super::draw_statusbar(&mut buf, &bar, w, h)?;
607	
608	    stdout.write_all(&buf)?;
609	    stdout.flush()
610	}
611	
612	// ── Worktree loading ──────────────────────────────────────────────────────────
613	
614	fn fetch_worktrees(repo_dir: &str) -> Vec<RepoWorktree> {
615	    let out = std::process::Command::new("git")
616	        .args(["worktree", "list", "--porcelain"])
617	        .current_dir(repo_dir)
618	        .output();
619	
620	    let Ok(out) = out else { return vec![]; };
621	    if !out.status.success() { return vec![]; }
622	    let text = String::from_utf8_lossy(&out.stdout);
623	
624	    let mut result = Vec::new();
625	    let mut first = true;
626	
627	    // Each worktree block is separated by a blank line.
628	    for block in text.split("\n\n") {
629	        let mut path = String::new();
630	        let mut head = String::new();
631	        let mut branch = String::new();
632	        let mut detached = false;
633	
634	        for line in block.lines() {
635	            if let Some(v) = line.strip_prefix("worktree ") {
636	                path = v.to_string();
637	            } else if let Some(v) = line.strip_prefix("HEAD ") {
638	                head = v.chars().take(8).collect();
639	            } else if let Some(v) = line.strip_prefix("branch refs/heads/") {
640	                branch = v.to_string();
641	            } else if line == "detached" {
642	                detached = true;
643	            }
644	        }
645	
646	        if path.is_empty() { continue; }
647	        if detached { branch = "(detached)".to_string(); }
648	        if branch.is_empty() { continue; } // bare worktree — skip
649	
650	        result.push(RepoWorktree { path, branch, head, is_main: first });
651	        first = false;
652	    }
653	
654	    result
655	}
656	
657	// ── Session loading ───────────────────────────────────────────────────────────
658	
659	// ── Text input prompt ─────────────────────────────────────────────────────────
660	
661	// ── New session wizard ────────────────────────────────────────────────────────
662	
663	/// A 4-step panel drawn over the bottom of the screen. Each completed step
664	/// stays visible with its confirmed value while the user fills the next one.
665	pub(super) fn new_session_wizard(stdout: &mut impl Write, repo_dir: &str, w: usize, h: usize) -> Option<NewSessionConfig> {
666	    const LABEL_W: usize = 24;
667	    // Panel rows: title, blank, agent, branch, name, prompt, blank  (7 rows + 1 status bar)
668	    const PANEL_H: usize = 7;
669	
670	    let t = crate::theme::get();
671	    let panel_top = h.saturating_sub(PANEL_H + 1);
672	
673	    let mut step = 0usize;           // 0=agent 1=branch 2=name 3=prompt
674	    let mut agent_sel = 0usize;
675	    let mut confirmed_agent = 0usize;
676	    let mut inputs = [String::new(), String::new(), String::new()]; // branch, name, prompt
677	
678	    execute!(stdout, cursor::Show).ok();
679	
680	    loop {
681	        // ── Draw panel ────────────────────────────────────────────────────────
682	        // Title row
683	        execute!(stdout, cursor::MoveTo(0, panel_top as u16)).ok();
684	        write!(stdout, "\x1b[{hd}m  New Session\x1b[0m", hd = t.header).ok();
685	        execute!(stdout, terminal::Clear(ClearType::UntilNewLine)).ok();
686	
687	        // Blank separator
688	        execute!(stdout, cursor::MoveTo(0, (panel_top + 1) as u16)).ok();
689	        execute!(stdout, terminal::Clear(ClearType::UntilNewLine)).ok();
690	
691	        let step_rows  = [panel_top + 2, panel_top + 3, panel_top + 4, panel_top + 5];
692	        let step_labels = ["  Agent", "  Worktree branch", "  Session name", "  Prompt"];
693	
694	        for (i, (&row, &label)) in step_rows.iter().zip(step_labels.iter()).enumerate() {
695	            execute!(stdout, cursor::MoveTo(0, row as u16)).ok();
696	            let lpart = format!("{label:<LABEL_W$}");
697	
698	            if i < step {
699	                // Completed — dim label, value in colour
700	                let val = if i == 0 {
701	                    let (name, _, col) = AGENTS[confirmed_agent];
702	                    format!("\x1b[38;5;{col}m{name}\x1b[0m")
703	                } else {
704	                    let v = inputs[i - 1].trim();
705	                    if v.is_empty() { format!("\x1b[{ft}m(skip)\x1b[0m", ft = t.text_faint) }
706	                    else            { format!("\x1b[{pm}m{v}\x1b[0m", pm = t.text_primary) }
707	                };
708	                write!(stdout, "\x1b[{dm}m{lpart}\x1b[0m{val}", dm = t.text_dim).ok();
709	            } else if i == step {
710	                // Active step
711	                write!(stdout, "\x1b[{pm}m{lpart}\x1b[0m", pm = t.text_primary).ok();
712	                if i == 0 {
713	                    // Inline agent picker
714	                    for (ai, (name, _, col)) in AGENTS.iter().enumerate() {
715	                        if ai > 0 { write!(stdout, "\x1b[{ft}m │ \x1b[0m", ft = t.text_faint).ok(); }
716	                        if ai == agent_sel {
717	                            write!(stdout, "\x1b[{sb};38;5;{col}m {name} \x1b[0m", sb = t.sel_bg).ok();
718	                        } else {
719	                            write!(stdout, "\x1b[{dm}m {name}\x1b[0m", dm = t.text_dim).ok();
720	                        }
721	                    }
722	                } else {
723	                    // Text input — print typed chars, terminal cursor sits here
724	                    write!(stdout, "\x1b[{pm}m{}\x1b[0m", inputs[i - 1], pm = t.text_primary).ok();
725	                }
726	            } else {
727	                // Future step — very dim label only
728	                write!(stdout, "\x1b[{ft}m{lpart}\x1b[0m", ft = t.text_faint).ok();
729	            }
730	            execute!(stdout, terminal::Clear(ClearType::UntilNewLine)).ok();
731	        }
732	
733	        // Trailing blank row
734	        let blank2 = panel_top + 6;
735	        if blank2 < h.saturating_sub(1) {
736	            execute!(stdout, cursor::MoveTo(0, blank2 as u16)).ok();
737	            execute!(stdout, terminal::Clear(ClearType::UntilNewLine)).ok();
738	        }
739	
740	        // Status bar hint
741	        let bar = if step == 0 {
742	            "  ↑↓/jk: select agent   enter: confirm   esc: cancel  "
743	        } else {
744	            "  type to enter   enter: next   esc: cancel  "
745	        };
746	        super::draw_statusbar(stdout, bar, w, h).ok();
747	
748	        // Position terminal cursor for text input steps
749	        if step > 0 {
750	            let row = step_rows[step];
751	            let col = (LABEL_W + inputs[step - 1].len()).min(w.saturating_sub(1));
752	            execute!(stdout, cursor::MoveTo(col as u16, row as u16)).ok();
753	        }
754	        stdout.flush().ok();
755	
756	        // ── Handle input ──────────────────────────────────────────────────────
757	        match event::read().ok()? {
758	            Event::Key(k) => match k.code {
759	                KeyCode::Esc => {
760	                    execute!(stdout, cursor::Hide).ok();
761	                    return None;
762	                }
763	                KeyCode::Up   | KeyCode::Char('k') if step == 0 => {
764	                    if agent_sel > 0 { agent_sel -= 1; }
765	                }
766	                KeyCode::Down | KeyCode::Char('j') if step == 0 => {
767	                    if agent_sel + 1 < AGENTS.len() { agent_sel += 1; }
768	                }
769	                KeyCode::Backspace if step > 0 => {
770	                    inputs[step - 1].pop();
771	                }
772	                KeyCode::Char(c) if step > 0 && !k.modifiers.contains(crossterm::event::KeyModifiers::CONTROL) => {
773	                    inputs[step - 1].push(c);
774	                }
775	                KeyCode::Enter => match step {
776	                    0 => { confirmed_agent = agent_sel; step = 1; }
777	                    1 | 2 => { step += 1; }
778	                    _ => {
779	                        execute!(stdout, cursor::Hide).ok();
780	                        let (agent_name, agent_cli, _) = AGENTS[confirmed_agent];
781	                        let branch_raw = inputs[0].trim().to_string();
782	                        return Some(NewSessionConfig {
783	                            agent_name: agent_name.to_string(),
784	                            agent_cli: agent_cli.to_string(),
785	                            branch: if branch_raw.is_empty() { None } else { Some(branch_raw) },
786	                            session_name: inputs[1].trim().to_string(),
787	                            prompt: inputs[2].trim().to_string(),
788	                            repo_dir: repo_dir.to_string(),
789	                        });
790	                    }
791	                },
792	                _ => {}
793	            },
794	            _ => {}
795	        }
796	    }
797	}
798	
799	// ── Helpers ───────────────────────────────────────────────────────────────────
800	
801	/// Create the worktree (if `cfg.branch` is set), copy the prompt to the
802	/// clipboard, then `exec` the agent. Only returns if `exec` failed.
803	pub(super) fn launch_new_session(cfg: NewSessionConfig) {
804	    use std::os::unix::process::CommandExt;
805	
806	    let launch_dir = if let Some(ref branch) = cfg.branch {
807	        let _ = create_worktree(&cfg.repo_dir, branch);
808	        let repo_path = std::path::Path::new(&cfg.repo_dir);
809	        let parent = repo_path.parent().unwrap_or(repo_path);
810	        let repo_name = repo_path.file_name()
811	            .map(|s| s.to_string_lossy().to_string())
812	            .unwrap_or_else(|| "repo".to_string());
813	        parent.join(format!("{repo_name}-{}", branch)).to_string_lossy().to_string()
814	    } else {
815	        cfg.repo_dir.clone()
816	    };
817	
818	    let prompt = cfg.prompt.trim().to_string();
819	    if !prompt.is_empty() {
820	        if let Ok(mut child) = std::process::Command::new("pbcopy")
821	            .stdin(std::process::Stdio::piped())
822	            .spawn()
823	        {
824	            if let Some(stdin) = child.stdin.as_mut() {
825	                let _ = stdin.write_all(prompt.as_bytes());
826	            }
827	            let _ = child.wait();
828	        }
829	    }
830	
831	    let session_name = cfg.session_name.trim().to_string();
832	    let mut cmd = std::process::Command::new(&cfg.agent_cli);
833	    if !launch_dir.is_empty() { cmd.current_dir(&launch_dir); }
834	    if !session_name.is_empty() { cmd.args(["-n", &session_name]); }
835	    if !prompt.is_empty() { cmd.arg(&prompt); }
836	    let err = cmd.exec();
837	    eprintln!("Failed to launch {}: {err}", cfg.agent_cli);
838	}
839	
840	pub(super) fn create_worktree(repo_dir: &str, branch: &str) -> String {
841	    let repo_path = std::path::Path::new(repo_dir);
842	    let parent = match repo_path.parent() {
843	        Some(p) => p,
844	        None => return "Error: cannot determine repo parent directory".to_string(),
845	    };
846	    let repo_name = repo_path
847	        .file_name()
848	        .map(|s| s.to_string_lossy().to_string())
849	        .unwrap_or_else(|| "repo".to_string());
850	    let wt_path = parent.join(format!("{repo_name}-{branch}"));
851	
852	    // Try -b (new branch) first; fall back to checking out an existing branch.
853	    let out = std::process::Command::new("git")
854	        .args(["worktree", "add", "-b", branch, wt_path.to_str().unwrap_or("")])
855	        .current_dir(repo_dir)
856	        .output();
857	
858	    match out {
859	        Err(e) => format!("Error: {e}"),
860	        Ok(o) if o.status.success() => {
861	            format!("Created worktree: {}", super::short_path(wt_path.to_str().unwrap_or("")))
862	        }
863	        Ok(o) => {
864	            let msg = String::from_utf8_lossy(&o.stderr);
865	            let first = msg.lines().find(|l| !l.trim().is_empty()).unwrap_or("unknown error");
866	            format!("Error: {first}")
867	        }
868	    }
869	}
870	
871	use super::agent_color;
872	
873	// Find which tracked repo the current directory belongs to — handles both the
874	// main worktree (starts_with match) and linked worktrees (git-common-dir match).
875	fn find_repo_for_cwd(repos: &[Repository]) -> Option<usize> {
876	    let cwd = env::current_dir().ok()?;
877	    let cwd_str = cwd.to_string_lossy();
878	
879	    // Main worktree: cwd is inside the repo root
880	    if let Some(idx) = repos.iter().position(|r| cwd_str.starts_with(r.directory.as_str())) {
881	        return Some(idx);
882	    }
883	
884	    // Linked worktree: git-common-dir points to the main repo's .git
885	    let out = std::process::Command::new("git")
886	        .args(["rev-parse", "--git-common-dir"])
887	        .current_dir(&cwd)
888	        .output()
889	        .ok()?;
890	    if !out.status.success() { return None; }
891	
892	    let common = String::from_utf8_lossy(&out.stdout).trim().to_string();
893	    let common_path = if std::path::Path::new(&common).is_absolute() {
894	        std::path::PathBuf::from(&common)
895	    } else {
896	        cwd.join(&common)
897	    };
898	
899	    // common_path is the .git dir; its parent is the repo root
900	    let repo_root = common_path.parent()?.to_string_lossy().to_string();
901	    repos.iter().position(|r| r.directory == repo_root)
902	}
