905	fn relative_time(dt: DateTime<Utc>) -> String {
906	    let secs = (Utc::now() - dt).num_seconds().max(0);
907	    if secs < 604_800 {
908	        match secs {
909	            s if s < 60     => "just now".to_string(),
910	            s if s < 3_600  => format!("{} min{} ago", s/60,     if s/60==1     {""} else {"s"}),
911	            s if s < 86_400 => format!("{} hr{} ago",  s/3_600,  if s/3_600==1  {""} else {"s"}),
912	            s               => format!("{} day{} ago", s/86_400, if s/86_400==1 {""} else {"s"}),
913	        }
914	    } else {
915	        dt.with_timezone(&Local).format("%m/%d/%y").to_string()
916	    }
917	}
