919	pub fn run_for_dir(repo_dir: &str) -> Result<bool> {
920	    let conn = db::connect()?;
921	    let mut repos = fetch_repos(&conn)?;
922	    let start = repos.iter().position(|r| r.directory == repo_dir);
923	
924	    let orig_hook = std::panic::take_hook();
925	    std::panic::set_hook(Box::new(move |info| {
926	        let mut out = io::stdout();
927	        let _ = execute!(out, LeaveAlternateScreen, cursor::Show);
928	        let _ = terminal::disable_raw_mode();
929	        orig_hook(info);
930	    }));
931	
932	    let mut stdout = io::stdout();
933	    terminal::enable_raw_mode()?;
934	    execute!(stdout, EnterAlternateScreen, cursor::Hide)?;
935	
936	    let outcome = tui_loop(&mut stdout, &mut repos, false, start);
937	
938	    execute!(stdout, LeaveAlternateScreen, cursor::Show)?;
939	    terminal::disable_raw_mode()?;
940	
941	    let outcome = outcome?;
942	    let quit_app = matches!(outcome, Some(TuiOutcome::Quit));
943	    match outcome {
944	        Some(TuiOutcome::ResumeSession { id, cwd }) => {
945	            super::show::resume_session(&id, &cwd);
946	        }
947	        Some(TuiOutcome::LaunchNewSession(cfg)) => { launch_new_session(cfg); }
948	        _ => {}
949	    }
950	
951	    Ok(quit_app)
952	}
953	
954	pub fn fetch_repos(conn: &rusqlite::Connection) -> Result<Vec<Repository>> {
955	    let mut stmt = conn.prepare("SELECT id, directory, remote, name FROM repositories ORDER BY name")?;
956	    let repos = stmt.query_map([], |row| {
957	        Ok(Repository {
958	            id: row.get(0)?,
959	            directory: row.get(1)?,
960	            remote: row.get(2)?,
961	            name: row.get(3)?,
962	        })
963	    })?
964	    .collect::<Result<Vec<_>, _>>()?;
965	    Ok(repos)
966	}
