1	//! Codex JSONL pipeline.
2	//!
3	//! Schema (per line):
4	//! ```
5	//! {"timestamp":"...","type":"<event_type>","payload":{...}}
6	//! ```
7	//!
8	//! Event types we care about:
9	//! - `session_meta`  — `payload.cwd`, `payload.timestamp`, etc.
10	//! - `response_item` — actual conversation turns. `payload.type` is one of
11	//!   `message`, `function_call`, `function_call_output`, `custom_tool_call`,
12	//!   `custom_tool_call_output`, `reasoning`.
13	//!   For `message`: `payload.role` is `user` | `assistant`, and
14	//!   `payload.content` is an array of `{type, text}` blocks where user
15	//!   blocks use `input_text` and assistant blocks use `output_text`.
16	//! - `turn_context`, `event_msg`, `compacted` — currently ignored for
17	//!   session_name extraction.
18	//!
19	//! Codex doesn't appear to have a `/rename` equivalent, so name_is_explicit
20	//! is always false. If/when one shows up, we'll detect it the same way we
21	//! do for Claude Code's `custom-title` events.
22	
23	use anyhow::{Context, Result};
24	use chrono::{DateTime, Utc};
25	use serde::Deserialize;
26	use serde_json::Value;
27	
28	use super::ParsedSession;
29	
30	pub fn parse_session(meta_bytes: &[u8], jsonl_bytes: &[u8]) -> Result<ParsedSession> {
31	    #[derive(Deserialize)]
32	    struct SessionMetadata {
33	        session_id: String,
34	        agent: Option<String>,
35	        created_at: Option<String>,
36	        branch: Option<String>,
37	    }
38	
39	    let meta: SessionMetadata = serde_json::from_slice(meta_bytes)
40	        .context("failed to parse metadata.json")?;
41	
42	    let created_at: DateTime<Utc> = meta
43	        .created_at
44	        .as_deref()
45	        .and_then(|s| DateTime::parse_from_rfc3339(s).ok())
46	        .map(|dt| dt.with_timezone(&Utc))
47	        .unwrap_or_else(Utc::now);
48	
49	    let agent_name = meta.agent.unwrap_or_else(|| "Codex".to_string());
50	    let branch = meta.branch.unwrap_or_default();
51	
52	    let mut cwd = String::new();
53	    let mut latest: Option<DateTime<Utc>> = None;
54	    let mut first_meaningful_prompt: Option<String> = None;
55	    let mut first_any_prompt: Option<String> = None;
56	
57	    for line in jsonl_bytes.split(|&b| b == b'\n') {
58	        if line.is_empty() { continue; }
59	        let v: Value = match serde_json::from_slice(line) {
60	            Ok(v) => v,
61	            Err(_) => continue,
62	        };
63	
64	        if let Some(ts) = v.get("timestamp").and_then(Value::as_str) {
65	            if let Ok(dt) = DateTime::parse_from_rfc3339(ts) {
66	                let dt: DateTime<Utc> = dt.with_timezone(&Utc);
67	                if latest.map_or(true, |l| dt > l) { latest = Some(dt); }
68	            }
69	        }
70	
71	        let event_type = v.get("type").and_then(Value::as_str).unwrap_or("");
72	        let payload = &v["payload"];
73	
74	        match event_type {
75	            "session_meta" => {
76	                if cwd.is_empty() {
77	                    if let Some(c) = payload.get("cwd").and_then(Value::as_str) {
78	                        cwd = c.to_string();
79	                    }
80	                }
81	            }
