1	use anyhow::{Context, Result};
2	use chrono::{DateTime, Local, Utc};
3	use crossterm::{
4	    cursor,
5	    event::{self, Event, KeyCode, KeyModifiers},
6	    execute,
7	    terminal::{self, ClearType, EnterAlternateScreen, LeaveAlternateScreen},
8	};
9	use serde_json::Value;
10	use std::collections::HashMap;
11	use std::io::{self, Write};
12	use std::path::PathBuf;
13	use std::sync::OnceLock;
14	
15	// ── Data model ────────────────────────────────────────────────────────────────
16	
17	enum Card {
18	    RepoLink  { name: String, dir: String, branch: String },
19	    Header    { title: Option<String>, cwd: String, branch: String, ts: String, agent: String },
20	    UserMsg   { ts: String, parts: Vec<UserPart>, author: Option<String> },
21	    AsstMsg   { ts: String, parts: Vec<AsstPart> },
22	    ToolRound { parts: Vec<AsstPart> },
23	    System    { ts: String, subtype: String, content: String },
24	}
25	
26	/// One entry per checkpoint commit, ordered oldest first. A turn with
27	/// timestamp T is attributed to the first entry whose `last_turn_ts >= T`.
28	struct CheckpointAuthor {
29	    last_turn_ts: DateTime<Utc>,
30	    label: String, // display name; email as fallback
31	}
32	
33	enum UserPart {
34	    Text(String),
35	    ToolResult { id: String, name: String, content: String, is_error: bool },
36	}
37	
38	enum AsstPart {
39	    Text(String),
40	    ToolCall { id: String, name: String, input: Value, result: Option<(String, bool)> },
41	}
42	
43	#[derive(Clone, PartialEq)]
44	enum Selectable {
45	    Card(usize),
46	    ToolHeader(usize),
47	    ToolCall(usize, usize), // (card_idx, tool_idx)
48	}
49	
50	// ── Entry point ───────────────────────────────────────────────────────────────
51	
52	/// Returns `Ok(true)` if the user pressed `q` (or Ctrl+C) — callers in a
53	/// parent TUI loop should treat that as a full-app exit. `Ok(false)` means
54	/// the user backed out normally (Esc/Left) and the parent should keep going.
55	pub fn run(session_id: &str) -> Result<bool> {
56	    run_at(session_id, None)
57	}
58	
59	pub fn run_at(session_id: &str, start_ts: Option<&str>) -> Result<bool> {
60	    let path = find_session(session_id)
61	        .with_context(|| format!("no session file found for '{session_id}'"))?;
62	
63	    let raw = std::fs::read_to_string(&path)
64	        .with_context(|| format!("cannot read {}", path.display()))?;
65	
66	    // Look up agent name and DB-stored session_name from the gossamer DB.
67	    let uuid = path.file_stem().and_then(|s| s.to_str()).unwrap_or("");
68	    let (agent, db_session_name) = if let Ok(conn) = crate::db::connect() {
69	        conn.query_row(
70	            "SELECT agent_name, COALESCE(session_name, '') FROM sessions WHERE session_id = ?1",
71	            [uuid],
72	            |row| Ok((row.get::<_, String>(0)?, row.get::<_, String>(1)?)),
73	        ).unwrap_or_default()
74	    } else { (String::new(), String::new()) };
75	
76	    let mut cards = parse(&raw, &agent);
77	    if cards.is_empty() {
78	        println!("No messages found.");
79	        return Ok(false);
80	    }
81	
82	    // Title fallback chain: JSONL custom-title (already set by parse) →
83	    // DB session_name (the indexer's first-meaningful-prompt) → first user
84	    // prompt in the JSONL. Covers sessions that were never /rename'd.
85	    let mut need_prompt_fallback = false;
86	    if let Some(Card::Header { title, .. }) = cards.iter_mut().find(|c| matches!(c, Card::Header { .. })) {
87	        if title.as_deref().map_or(true, str::is_empty) {
88	            if !db_session_name.trim().is_empty() {
89	                *title = Some(db_session_name);
90	            } else {
91	                need_prompt_fallback = true;
92	            }
93	        }
94	    }
95	    if need_prompt_fallback {
96	        let first_user_text: Option<String> = cards.iter().find_map(|c| {
97	            if let Card::UserMsg { parts, .. } = c {
98	                parts.iter().find_map(|p| {
99	                    if let UserPart::Text(t) = p {
100	                        let trimmed = t.trim();
101	                        if trimmed.is_empty() { None } else { Some(trimmed.to_string()) }
102	                    } else { None }
103	                })
104	            } else { None }
105	        });
106	        if let Some(text) = first_user_text {
107	            if let Some(Card::Header { title, .. }) = cards.iter_mut().find(|c| matches!(c, Card::Header { .. })) {
108	                *title = Some(text);
109	            }
110	        }
111	    }
112	
113	    // Extract branch and cwd from the Header before cards are consumed by pager.
114	    let session_branch = cards.iter().find_map(|c| {
115	        if let Card::Header { branch, .. } = c { Some(branch.clone()) } else { None }
116	    }).unwrap_or_default();
117	    let session_cwd = cards.iter().find_map(|c| {
118	        if let Card::Header { cwd, .. } = c { Some(cwd.clone()) } else { None }
119	    }).unwrap_or_default();
120	
121	    // Attribute each user message to the checkpoint author, or fall back to
122	    // git config user.name for sessions not yet indexed from the checkpoint branch.
123	    let authors = fetch_authors(uuid);
124	    if !authors.is_empty() {
125	        for card in cards.iter_mut() {
126	            if let Card::UserMsg { ts, author, .. } = card {
127	                *author = attribute(&authors, ts);
128	            }
129	        }
130	    } else if let Some(name) = git_config_user(&session_cwd) {
131	        for card in cards.iter_mut() {
132	            if let Card::UserMsg { author, .. } = card {
133	                *author = Some(name.clone());
134	            }
135	        }
136	    }
137	
138	    // Look up the repo that owns this session's cwd and prepend a RepoLink card.
139	    if let Ok(conn) = crate::db::connect() {
140	        if let Ok((repo_name, repo_dir)) = conn.query_row(
141	            "SELECT name, directory FROM repositories
142	             WHERE ?1 LIKE (directory || '%')
143	             ORDER BY LENGTH(directory) DESC LIMIT 1",
144	            [&session_cwd],
145	            |row| Ok((row.get::<_, String>(0)?, row.get::<_, String>(1)?)),
146	        ) {
147	            cards.insert(0, Card::RepoLink { name: repo_name, dir: repo_dir, branch: session_branch.clone() });
148	        }
149	    }
150	
151	    let mut quit_app = false;
152	    loop {
153	        match pager(&cards, start_ts)? {
154	            PagerOutcome::Resume => {
155	                do_resume(&agent, session_id, &session_branch, &session_cwd);
156	                break;
157	            }
158	            PagerOutcome::Delete => { super::clean::run(session_id, false)?; break; }
159	            PagerOutcome::Quit   => { quit_app = true; break; }
160	            PagerOutcome::Back   => break,
161	            PagerOutcome::GoToSessions => {
162	                if super::sessions::run(false, false)? { quit_app = true; }
163	                break;
164	            }
165	            PagerOutcome::GoToRepo(dir) => {
166	                if super::status::run_for_dir(&dir)? { quit_app = true; break; }
167	            }
168	        }
169	    }
170	
171	    Ok(quit_app)
172	}
173	
174	fn fetch_authors(session_id: &str) -> Vec<CheckpointAuthor> {
175	    let Ok(conn) = crate::db::connect() else { return Vec::new(); };
176	    let Ok(mut stmt) = conn.prepare(
177	        "SELECT last_turn_ts, author_name, author_email, COALESCE(os_user, '')
178	           FROM checkpoints
179	          WHERE session_id = ?1
180	       ORDER BY checkpoint_number ASC"
181	    ) else { return Vec::new(); };
182	
183	    let rows = stmt.query_map([session_id], |row| {
184	        let ts: String = row.get(0)?;
185	        let name: String = row.get(1)?;
186	        let email: String = row.get(2)?;
187	        let os_user: String = row.get(3)?;
188	        Ok((ts, name, email, os_user))
189	    });
190	    let Ok(rows) = rows else { return Vec::new(); };
191	
192	    let mut out = Vec::new();
193	    for r in rows.flatten() {
194	        let (ts_s, name, email, os_user) = r;
195	        let Ok(dt) = DateTime::parse_from_rfc3339(&ts_s) else { continue };
196	        let label = if !name.trim().is_empty() {
197	            name
198	        } else if !email.trim().is_empty() {
199	            email
200	        } else {
201	            os_user
202	        };
203	        if label.is_empty() { continue; }
204	        out.push(CheckpointAuthor {
205	            last_turn_ts: dt.with_timezone(&Utc),
206	            label,
207	        });
208	    }
209	    out
210	}
211	
212	fn attribute(authors: &[CheckpointAuthor], ts: &str) -> Option<String> {
213	    let dt = DateTime::parse_from_rfc3339(ts).ok()?.with_timezone(&Utc);
214	    // Earliest checkpoint whose last_turn_ts >= the card's timestamp.
215	    for a in authors {
216	        if a.last_turn_ts >= dt {
217	            return Some(a.label.clone());
218	        }
219	    }
220	    // Card's timestamp is past every checkpoint we've seen — attribute to
221	    // the most recent author (latest checkpoint).
222	    authors.last().map(|a| a.label.clone())
223	}
