225	fn git_config_user(cwd: &str) -> Option<String> {
226	    for key in ["user.name", "user.email"] {
227	        let mut cmd = std::process::Command::new("git");
228	        cmd.args(["config", key]);
229	        if !cwd.is_empty() && std::path::Path::new(cwd).exists() {
230	            cmd.current_dir(cwd);
231	        }
232	        if let Some(s) = cmd.output().ok()
233	            .filter(|o| o.status.success())
234	            .and_then(|o| String::from_utf8(o.stdout).ok())
235	            .map(|s| s.trim().to_string())
236	            .filter(|s| !s.is_empty())
237	        {
238	            return Some(s);
239	        }
240	    }
241	    None
242	}
