512	
513	fn card_text(card: &Card) -> String {
514	    let mut out = String::new();
515	    match card {
516	        Card::RepoLink { name, dir, branch } => {
517	            out.push_str(name); out.push('\n');
518	            out.push_str(dir);  out.push('\n');
519	            if !branch.is_empty() { out.push_str(branch); out.push('\n'); }
520	        }
521	        Card::Header { title, cwd, branch, agent, .. } => {
522	            if let Some(t) = title { out.push_str(t); out.push('\n'); }
523	            if !cwd.is_empty()    { out.push_str(cwd);               out.push('\n'); }
524	            if !branch.is_empty() { out.push_str(&format!("[{branch}]")); out.push('\n'); }
525	            if !agent.is_empty()  { out.push_str(agent); out.push('\n'); }
526	        }
527	        Card::System { content, .. } => { if !content.is_empty() { out.push_str(content); out.push('\n'); } }
528	        Card::UserMsg { parts, .. } => {
529	            for part in parts {
530	                match part {
531	                    UserPart::Text(t) => { out.push_str(t); out.push('\n'); }
532	                    UserPart::ToolResult { name, content, .. } => {
533	                        out.push_str(&format!("[Result: {name}]\n{content}\n"));
534	                    }
535	                }
536	            }
537	        }
538	        Card::AsstMsg { parts, .. } => {
539	            for part in parts {
540	                if let AsstPart::Text(t) = part { out.push_str(t); out.push('\n'); }
541	            }
542	        }
543	        Card::ToolRound { parts } => {
544	            for part in parts {
545	                if let AsstPart::ToolCall { name, input, result, .. } = part {
546	                    out.push_str(&format!("[Tool: {name}]\n"));
547	                    if let Some(obj) = input.as_object() {
548	                        for (k, v) in obj {
549	                            let val = if let Value::String(s) = v { s.clone() } else { v.to_string() };
550	                            out.push_str(&format!("{k}: {val}\n"));
551	                        }
552	                    }
553	                    if let Some((content, _)) = result {
554	                        out.push_str(&format!("[Result]\n{content}\n"));
555	                    }
556	                }
557	            }
558	        }
559	    }
560	    out
561	}
