563	fn tool_call_text(part: &AsstPart) -> String {
564	    let mut out = String::new();
565	    if let AsstPart::ToolCall { name, input, result, .. } = part {
566	        out.push_str(&format!("[Tool: {name}]\n"));
567	        if let Some(obj) = input.as_object() {
568	            for (k, v) in obj {
569	                let val = if let Value::String(s) = v { s.clone() } else { v.to_string() };
570	                out.push_str(&format!("{k}: {val}\n"));
571	            }
572	        }
573	        if let Some((content, _)) = result { out.push_str(&format!("[Result]\n{content}\n")); }
574	    }
575	    out
576	}
