628	use super::agent_color;
629	
630	fn render_card(card: &Card, width: usize, agent: &str) -> Vec<String> {
631	    let th = crate::theme::get();
632	    let mut lines: Vec<String> = Vec::new();
633	    let w = width.saturating_sub(2);
634	
635	    match card {
636	        Card::RepoLink { name, dir, branch } => {
637	            let home = std::env::var("HOME").unwrap_or_default();
638	            let short = if !home.is_empty() && dir.starts_with(&home) {
639	                format!("~{}", &dir[home.len()..])
640	            } else { dir.clone() };
641	            let branch_part = if !branch.is_empty() {
642	                format!("  \x1b[{lb}m[{branch}]\x1b[0m", lb = th.label)
643	            } else { String::new() };
644	            lines.push(format!(
645	                "\x1b[{dm}m▸ repo  \x1b[0m\x1b[1;{lk}m{name}\x1b[0m  \x1b[{dm}m{short}\x1b[0m{branch_part}",
646	                dm = th.text_dim, lk = th.link,
647	            ));
648	        }
649	        Card::Header { title, cwd: _, branch: _, ts, agent: hdr_agent } => {
650	            let title_str = title.as_deref().unwrap_or("(untitled session)");
651	            let (agent_label, agent_col) = if hdr_agent.is_empty() {
652	                ("claude".to_string(), 75u8)
653	            } else {
654	                (hdr_agent.to_lowercase(), agent_color(hdr_agent))
655	            };
656	            let agent_part = format!("  \x1b[1;38;5;{agent_col}m{agent_label}\x1b[0m");
657	            let ts_part = if !ts.is_empty() {
658	                format!("  \x1b[{dm}m{}\x1b[0m", rel_time(ts), dm = th.text_dim)
659	            } else { String::new() };
660	            lines.push(format!("\x1b[{hd}m{title_str}\x1b[0m{agent_part}{ts_part}", hd = th.header));
661	        }
662	        Card::System { ts, subtype, content } => {
663	            lines.push(format!("\x1b[{dm}m── {subtype}  {}\x1b[0m", rel_time(ts), dm = th.text_dim));
664	            lines.push(String::new());
665	            for l in wrap(content, w) { lines.push(format!("  \x1b[{dm}m{l}\x1b[0m", dm = th.text_dim)); }
666	        }
667	        Card::UserMsg { ts, parts, author } => {
668	            let label = author.as_deref().unwrap_or("user");
669	            lines.push(format!(
670	                "\x1b[1;{fr}m── {label}  \x1b[0m\x1b[{dm}m{}\x1b[0m",
671	                rel_time(ts), fr = th.fresh, dm = th.text_dim,
672	            ));
673	            for part in parts {
674	                match part {
675	                    UserPart::Text(text) => {
676	                        lines.push(String::new());
677	                        if is_xml_block(text) {
678	                            let tag = xml_root_tag(text);
679	                            let n = text.lines().count();
680	                            if n > 4 {
681	                                // Long XML block: collapse to one line.
682	                                lines.push(format!("  \x1b[{ft}m‹{tag}  {n} lines›\x1b[0m", ft = th.text_faint));
683	                            } else {
684	                                // Short XML block: strip tags, show content inline.
685	                                let content = strip_xml_tags(text);
686	                                let content = content.split_whitespace().collect::<Vec<_>>().join(" ");
687	                                let avail = w.saturating_sub(tag.len() + 8);
688	                                let preview: String = content.chars().take(avail).collect();
689	                                let suffix = if content.chars().count() > avail { " …" } else { "" };
690	                                if preview.is_empty() {
691	                                    lines.push(format!("  \x1b[{ft}m‹{tag}›\x1b[0m", ft = th.text_faint));
692	                                } else {
693	                                    lines.push(format!("  \x1b[{ft}m‹{tag}›  {preview}{suffix}\x1b[0m", ft = th.text_faint));
694	                                }
695	                            }
696	                        } else {
697	                            for l in render_md(text, w.saturating_sub(2)) { lines.push(format!("  {l}")); }
698	                        }
699	                    }
700	                    UserPart::ToolResult { name, content, is_error, .. } => {
701	                        let col = if *is_error { th.error } else { th.tool_ok };
702	                        lines.push(format!("\x1b[{col}m  ◀ {name}\x1b[0m"));
703	                        let visible: Vec<&str> = content.lines()
704	                            .filter(|l| !l.trim().is_empty()).take(8).collect();
705	                        for l in wrap(&visible.join("\n"), w.saturating_sub(4)) {
706	                            lines.push(format!("\x1b[{dm}m    {l}\x1b[0m", dm = th.text_dim));
707	                        }
708	                        let total = content.lines().filter(|l| !l.trim().is_empty()).count();
709	                        if total > 8 {
710	                            lines.push(format!("\x1b[{ft}m    … {} more lines\x1b[0m", total - 8, ft = th.text_faint));
711	                        }
712	                    }
713	                }
714	            }
715	        }
716	        Card::AsstMsg { ts, parts } => {
717	            let (agent_label, agent_col) = if agent.is_empty() {
718	                ("claude".to_string(), 75u8)
719	            } else {
720	                (agent.to_lowercase(), agent_color(agent))
721	            };
722	            lines.push(format!(
723	                "\x1b[1;38;5;{agent_col}m── {agent_label}  \x1b[0m\x1b[{dm}m{}\x1b[0m",
724	                rel_time(ts), dm = th.text_dim,
725	            ));
726	            for part in parts {
727	                if let AsstPart::Text(text) = part {
728	                    lines.push(String::new());
729	                    for l in render_md(text, w.saturating_sub(2)) { lines.push(format!("  {l}")); }
730	                }
731	            }
732	        }
733	        Card::ToolRound { .. } => {} // handled in build_flat
734	    }
735	
736	    lines.push(String::new());
737	    lines
738	}
