814	fn xml_root_tag(text: &str) -> &str {
815	    let t = text.trim_start();
816	    let inner = t.strip_prefix('<').unwrap_or(t);
817	    let inner = inner.trim_start_matches(['!', '/']);
818	    let end = inner.find(|c: char| c == '>' || c == ' ' || c == '\n').unwrap_or(inner.len());
819	    let tag = &inner[..end];
820	    if tag.is_empty() { "xml" } else { tag }
