823	fn strip_xml_tags(text: &str) -> String {
824	    let mut out = String::new();
825	    let mut in_tag = false;
826	    for c in text.chars() {
827	        match c {
828	            '<' => { in_tag = true; }
829	            '>' => { in_tag = false; }
830	            '\n' if in_tag => {}
831	            _ if !in_tag => out.push(c),
832	            _ => {}
833	        }
834	    }
835	    out
836	}
