838	fn wrap(text: &str, width: usize) -> Vec<String> {
839	    if width < 4 { return text.lines().map(str::to_string).collect(); }
840	    let mut out = Vec::new();
841	    for raw_line in text.lines() {
842	        if raw_line.is_empty() { out.push(String::new()); continue; }
843	        let mut remaining = raw_line;
844	        loop {
845	            if remaining.chars().count() <= width {
846	                out.push(remaining.to_string());
847	                break;
848	            }
849	            let break_pos = remaining.chars().take(width)
850	                .collect::<String>()
851	                .rfind(' ')
852	                .unwrap_or(width);
853	            let byte_pos = remaining.char_indices().nth(break_pos)
854	                .map(|(i, _)| i)
855	                .unwrap_or(remaining.len());
856	            out.push(remaining[..byte_pos].to_string());
857	            remaining = remaining[byte_pos..].trim_start_matches(' ');
858	        }
859	    }
860	    out
861	}
