863	fn rel_time(iso: &str) -> String {
864	    let Ok(dt) = DateTime::parse_from_rfc3339(iso) else { return iso.to_string(); };
865	    let secs = (Utc::now() - dt.with_timezone(&Utc)).num_seconds().max(0);
866	    if secs < 604_800 {
867	        match secs {
868	            s if s < 60     => "just now".into(),
869	            s if s < 3_600  => format!("{} min{} ago", s/60,     if s/60==1     {""} else {"s"}),
870	            s if s < 86_400 => format!("{} hr{} ago",  s/3_600,  if s/3_600==1  {""} else {"s"}),
871	            s               => format!("{} day{} ago", s/86_400, if s/86_400==1 {""} else {"s"}),
872	        }
873	    } else {
874	        dt.with_timezone(&Local).format("%m/%d/%y").to_string()
875	    }
876	}
