880	fn git_current_branch(cwd: &str) -> Option<String> {
881	    let out = std::process::Command::new("git")
882	        .args(["rev-parse", "--abbrev-ref", "HEAD"])
883	        .current_dir(cwd)
884	        .output()
885	        .ok()?;
886	    if !out.status.success() { return None; }
887	    let s = String::from_utf8_lossy(&out.stdout).trim().to_string();
888	    if s.is_empty() || s == "HEAD" { None } else { Some(s) }
889	}
890	
891	fn create_resume_worktree(cwd: &str, branch: &str) -> Option<String> {
892	    let root_out = std::process::Command::new("git")
893	        .args(["rev-parse", "--show-toplevel"])
894	        .current_dir(cwd)
895	        .output()
896	        .ok()?;
897	    if !root_out.status.success() { return None; }
898	    let repo_root = String::from_utf8_lossy(&root_out.stdout).trim().to_string();
899	
900	    let repo_path = std::path::Path::new(&repo_root);
901	    let parent = repo_path.parent()?;
902	    let repo_name = repo_path.file_name()?.to_str()?;
903	    let wt_path = parent.join(format!("{repo_name}-{branch}"));
904	
905	    // Branch already exists; add a worktree pointing at it.
906	    let _ = std::process::Command::new("git")
907	        .args(["worktree", "add", wt_path.to_str()?, branch])
908	        .current_dir(&repo_root)
909	        .output();
910	
911	    if wt_path.exists() { Some(wt_path.to_string_lossy().to_string()) } else { None }
912	}
