914	fn resume_via_entire(dir: &str, branch: &str) {
915	    use std::os::unix::process::CommandExt;
916	
917	    let launch_dir = if !branch.is_empty() {
918	        let current = git_current_branch(dir);
919	        if current.as_deref() != Some(branch) {
920	            create_resume_worktree(dir, branch).unwrap_or_else(|| dir.to_string())
921	        } else {
922	            dir.to_string()
923	        }
924	    } else {
925	        dir.to_string()
926	    };
927	
928	    let mut entire = std::process::Command::new("entire");
929	    entire.arg("resume").current_dir(&launch_dir);
930	    if !branch.is_empty() { entire.arg(branch); }
931	
932	    let Ok(out) = entire.output() else { eprintln!("entire resume failed"); return; };
933	
934	    let cmd_str = String::from_utf8_lossy(&out.stdout).trim().to_string();
935	    if cmd_str.is_empty() { eprintln!("entire resume returned no command"); return; }
936	
937	    let mut parts = cmd_str.split_whitespace();
938	    let Some(prog) = parts.next() else { return; };
939	    let args: Vec<&str> = parts.collect();
940	    let err = std::process::Command::new(prog).args(&args).current_dir(&launch_dir).exec();
941	    eprintln!("exec failed: {err}");
942	}
