944	/// Find a Claude session by ID. Returns `(cwd, git_branch)` from the JSONL if found,
945	/// so `claude --resume` can be run from the correct directory and branch is known.
946	fn find_claude_session_cwd(session_id: &str) -> Option<(String, String)> {
947	    use std::io::BufRead;
948	    let home = std::env::var("HOME").ok()?;
949	    let projects = std::path::PathBuf::from(&home).join(".claude/projects");
950	    for dir in std::fs::read_dir(&projects).ok()?.flatten() {
951	        let jsonl = dir.path().join(format!("{session_id}.jsonl"));
952	        if !jsonl.exists() { continue; }
953	        let Ok(file) = std::fs::File::open(&jsonl) else { return Some((String::new(), String::new())); };
954	        let mut cwd = String::new();
955	        let mut branch = String::new();
956	        for line in std::io::BufReader::new(file).lines().flatten() {
957	            let Ok(v) = serde_json::from_str::<serde_json::Value>(&line) else { continue };
958	            if matches!(v["type"].as_str(), Some("user") | Some("system")) {
959	                if cwd.is_empty() {
960	                    if let Some(c) = v["cwd"].as_str() { cwd = c.to_string(); }
961	                }
962	                if branch.is_empty() {
963	                    if let Some(b) = v["gitBranch"].as_str() { branch = b.to_string(); }
964	                }
965	                if !cwd.is_empty() && !branch.is_empty() { break; }
966	            }
967	        }
968	        return Some((cwd, branch));
969	    }
970	    None
971	}
