973	fn do_resume(_agent: &str, session_id: &str, session_branch: &str, session_cwd: &str) {
974	    let current = git_current_branch(session_cwd);
975	    let same_branch = !session_branch.is_empty()
976	        && current.as_deref() == Some(session_branch);
977	
978	    let dir = if same_branch || session_branch.is_empty() {
979	        session_cwd.to_string()
980	    } else {
981	        create_resume_worktree(session_cwd, session_branch)
982	            .unwrap_or_else(|| session_cwd.to_string())
983	    };
984	
985	    resume_session(session_id, &dir);
986	}
