988	/// Resume a session by ID, falling back to `entire resume` if the Claude JSONL is absent.
989	/// `fallback_cwd` is used for `entire resume` if the Claude session isn't found.
990	pub fn resume_session(session_id: &str, fallback_cwd: &str) {
991	    use std::os::unix::process::CommandExt;
992	    if let Some((session_cwd, session_branch)) = find_claude_session_cwd(session_id) {
993	        let launch_dir = if session_cwd.is_empty() || !std::path::Path::new(&session_cwd).exists() {
994	            fallback_cwd.to_string()
995	        } else {
996	            session_cwd
997	        };
998	        let err = std::process::Command::new("claude")
999	            .arg("--resume")
1000	            .arg(session_id)
1001	            .current_dir(&launch_dir)
1002	            .exec();
1003	        eprintln!("exec failed: {err}");
1004	        // exec failed — fall back to entire resume, checking out the session branch first
1005	        resume_via_entire(&launch_dir, &session_branch);
1006	    } else {
1007	        resume_via_entire(fallback_cwd, "");
1008	    }
1009	}
