1013	fn build_flat(
1014	    cards: &[Card],
1015	    term_w: usize,
1016	    collapsed: &std::collections::HashSet<usize>,
1017	) -> (Vec<(usize, String)>, Vec<Selectable>, Vec<usize>) {
1018	    let w = term_w.saturating_sub(2);
1019	    let mut flat: Vec<(usize, String)> = Vec::new();
1020	    let mut selectables: Vec<Selectable> = Vec::new();
1021	    let mut starts: Vec<usize> = Vec::new();
1022	
1023	    // Pull the agent name from the Header card so render_card can use it.
1024	    let agent: &str = cards.iter().find_map(|c| {
1025	        if let Card::Header { agent, .. } = c { Some(agent.as_str()) } else { None }
1026	    }).unwrap_or("");
1027	
1028	    for (card_idx, card) in cards.iter().enumerate() {
1029	        if let Card::ToolRound { parts } = card {
1030	            if collapsed.contains(&card_idx) {
1031	                let si = selectables.len();
1032	                starts.push(flat.len());
1033	                selectables.push(Selectable::Card(card_idx));
1034	                for l in render_tool_summary(parts) { flat.push((si, l)); }
1035	            } else {
1036	                // Header row (collapses the round when space is pressed)
1037	                let si = selectables.len();
1038	                starts.push(flat.len());
1039	                selectables.push(Selectable::ToolHeader(card_idx));
1040	                for l in render_tool_header(parts) { flat.push((si, l)); }
1041	                // One selectable per individual tool call
1042	                for (tool_idx, part) in parts.iter().enumerate() {
1043	                    let si = selectables.len();
1044	                    starts.push(flat.len());
1045	                    selectables.push(Selectable::ToolCall(card_idx, tool_idx));
1046	                    for l in render_one_tool_call(part, w) { flat.push((si, l)); }
1047	                }
1048	            }
1049	        } else {
1050	            let si = selectables.len();
1051	            starts.push(flat.len());
1052	            selectables.push(Selectable::Card(card_idx));
1053	            for l in render_card(card, w, agent) { flat.push((si, l)); }
1054	        }
1055	    }
1056	
1057	    (flat, selectables, starts)
1058	}
