1060	// `Back` returns to whatever called show (the sessions list, the repo TUI, or
1061	// the CLI). `Quit` propagates a full-app exit so q from anywhere quits.
1062	enum PagerOutcome { Back, Quit, Resume, Delete, GoToSessions, GoToRepo(String) }
1063	
1064	fn pager(cards: &[Card], start_ts: Option<&str>) -> Result<PagerOutcome> {
1065	    let (term_w, term_h) = terminal::size().unwrap_or((120, 40));
1066	    let mut w = term_w as usize;
1067	    let mut h = (term_h as usize).saturating_sub(1);
1068	
1069	    let mut collapsed: std::collections::HashSet<usize> = cards.iter().enumerate()
1070	        .filter_map(|(i, c)| if matches!(c, Card::ToolRound { .. }) { Some(i) } else { None })
1071	        .collect();
1072	
1073	    let (mut flat, mut selectables, mut starts) = build_flat(&cards, w, &collapsed);
1074	
1075	    let mut stdout = io::stdout();
1076	
1077	    let orig_hook = std::panic::take_hook();
1078	    std::panic::set_hook(Box::new(move |info| {
1079	        let mut out = io::stdout();
1080	        let _ = execute!(out, LeaveAlternateScreen, cursor::Show);
1081	        let _ = terminal::disable_raw_mode();
1082	        orig_hook(info);
1083	    }));
1084	
1085	    terminal::enable_raw_mode()?;
1086	    execute!(stdout, EnterAlternateScreen, cursor::Hide)?;
1087	
1088	    // If a target timestamp was given, jump to the first card whose ts matches.
1089	    // Otherwise land on the first non-navigation card (skip RepoLink and Header).
1090	    let initial_sel = start_ts.and_then(|ts| {
1091	        cards.iter().enumerate().find_map(|(ci, card)| {
1092	            let card_ts = match card {
1093	                Card::UserMsg { ts, .. } | Card::AsstMsg { ts, .. } | Card::System { ts, .. } => ts.as_str(),
1094	                _ => return None,
1095	            };
1096	            if card_ts == ts {
1097	                selectables.iter().position(|s| *s == Selectable::Card(ci))
1098	            } else {
1099	                None
1100	            }
1101	        })
1102	    }).unwrap_or_else(|| selectables.len().saturating_sub(1));
1103	
1104	    let mut sel: usize = initial_sel;
1105	    let mut scroll: usize = 0;
1106	    let mut flash:  Option<&str> = None;
1107	    let mut awaiting_delete = false;
1108	
1109	    let result: Result<PagerOutcome> = loop {
1110	        let s = starts[sel];
1111	        let e = starts.get(sel + 1).copied().unwrap_or(flat.len());
1112	        if s < scroll          { scroll = s; }
1113	        else if e > scroll + h { scroll = e.saturating_sub(h); }
1114	
1115	        if let Err(err) = draw(&mut stdout, &flat, &starts, sel, scroll, h, w, selectables.len(), flash) {
1116	            break Err(anyhow::anyhow!(err));
1117	        }
1118	
1119	        match event::read() {
1120	            Err(e) => break Err(e.into()),
1121	            Ok(Event::Key(k)) => {
1122	                let prev_flash = flash.take();
1123	                match (k.code, k.modifiers) {
1124	                    (KeyCode::Char('q'), _) => break Ok(PagerOutcome::Quit),
1125	                    (KeyCode::Char('c'), KeyModifiers::CONTROL) => break Ok(PagerOutcome::Quit),
1126	                    (KeyCode::Esc | KeyCode::Left, _) => break Ok(PagerOutcome::Back),
1127	                    (KeyCode::Char('r'), _) => break Ok(PagerOutcome::Resume),
1128	                    (KeyCode::Char('d'), _) => {
1129	                        awaiting_delete = true;
1130	                        flash = Some("  Delete session? Press y to confirm, any other key to cancel  ");
1131	                        continue;
1132	                    }
1133	                    (KeyCode::Char('y'), _) if awaiting_delete => {
1134	                        break Ok(PagerOutcome::Delete);
1135	                    }
1136	
1137	                    (KeyCode::Down | KeyCode::Char('j'), _) => {
1138	                        if sel + 1 < selectables.len() { sel += 1; }
1139	                    }
1140	                    (KeyCode::Up | KeyCode::Char('k'), _) => {
1141	                        if sel > 0 { sel -= 1; }
1142	                    }
1143	                    (KeyCode::Char('g'), _) => { sel = 0; }
1144	                    (KeyCode::Char('G'), _) => { sel = selectables.len().saturating_sub(1); }
1145	                    (KeyCode::Char('u'), _) | (KeyCode::PageUp, _) => {
1146	                        scroll = scroll.saturating_sub(h / 2);
1147	                        sel = flat[scroll].0;
1148	                    }
1149	                    (KeyCode::PageDown, _) => {
1150	                        scroll = (scroll + h / 2).min(flat.len().saturating_sub(h));
1151	                        sel = flat[scroll].0;
1152	                    }
1153	
1154	                    (KeyCode::Char('y'), _) | (KeyCode::Char('c'), _) => {
1155	                        let text = match &selectables[sel] {
1156	                            Selectable::Card(ci)         => card_text(&cards[*ci]),
1157	                            Selectable::ToolHeader(ci)   => card_text(&cards[*ci]),
1158	                            Selectable::ToolCall(ci, ti) => {
1159	                                if let Card::ToolRound { parts } = &cards[*ci] {
1160	                                    parts.get(*ti).map_or(String::new(), tool_call_text)
1161	                                } else { String::new() }
1162	                            }
1163	                        };
1164	                        copy_to_clipboard(&text);
1165	                        flash = Some("  ✓ copied to clipboard  ");
1166	                    }
1167	
1168	                    // Space/Right/Enter: expand ToolRound, collapse via header, or navigate
1169	                    (KeyCode::Char(' ') | KeyCode::Right | KeyCode::Enter, _) => {
1170	                        let expand_action = match &selectables[sel] {
1171	                            Selectable::Card(ci) if matches!(&cards[*ci], Card::ToolRound { .. }) => {
1172	                                Some((true, *ci))
1173	                            }
1174	                            Selectable::ToolHeader(ci) => Some((false, *ci)),
1175	                            _ => None,
1176	                        };
1177	                        if let Some((expand, card_idx)) = expand_action {
1178	                            if expand { collapsed.remove(&card_idx); } else { collapsed.insert(card_idx); }
1179	                            let (nf, ns, nst) = build_flat(cards, w, &collapsed);
1180	                            flat   = nf;
