1186	                            }.unwrap_or_else(|| sel.min(ns.len().saturating_sub(1)));
1187	                            selectables = ns;
1188	                        } else if let Selectable::Card(ci) = &selectables[sel] {
1189	                            match &cards[*ci] {
1190	                                Card::RepoLink { dir, .. } => {
1191	                                    break Ok(PagerOutcome::GoToRepo(dir.clone()));
1192	                                }
1193	                                Card::Header { .. } => {
