1233	}
1234	
1235	fn draw(
1236	    stdout: &mut impl Write,
1237	    flat:   &[(usize, String)],
1238	    starts: &[usize],
1239	    sel:    usize,
1240	    scroll: usize,
1241	    h:      usize,
