18	gr() {
19	  local tmp
20	  tmp=$(mktemp)
21	  GOSSAMER_CDPATH="$tmp" gossamer repo
22	  local dest
23	  dest=$(cat "$tmp" 2>/dev/null)
24	  rm -f "$tmp"
25	  [[ -n "$dest" ]] && cd "$dest"
26	}"#;
