        // ── Handle input ──────────────────────────────────────────────────────
        match event::read().ok()? {
            Event::Key(k) => match k.code {
                KeyCode::Esc => {
                    execute!(stdout, cursor::Hide).ok();
                    return None;
                }
                KeyCode::Backspace => { inputs[step].pop(); }
                KeyCode::Char(c) if !k.modifiers.contains(crossterm::event::KeyModifiers::CONTROL) => {
                    inputs[step].push(c);
                }
                KeyCode::Enter => match step {
                    0 | 1 => { step += 1; }
